// ---------------------------------------------------------------------------
// Golden Set Evaluator
// ---------------------------------------------------------------------------
//
// Scores pipeline results against golden expectations. Returns a structured
// report that can be serialised to JSON for nightly CI artifacts.

import type { Finding } from '../../src/types/index.js';
import type { ScenarioExpectation } from './expectations.js';

export interface EvalDetail {
  check: string;
  pass: boolean;
  detail: string;
}

export interface ScenarioEvalResult {
  scenario: string;
  pass: boolean;
  score: number;
  checks: EvalDetail[];
}

export interface EvalReport {
  timestamp: string;
  scenarios: Record<string, ScenarioEvalResult>;
  overallPass: boolean;
  overallScore: number;
}

function allFindingsText(findings: Finding[]): string {
  return findings
    .map((f) => [
      f.title,
      f.reasoningSummary,
      ...f.evidence.map((e) => `${e.path} ${e.note}`),
    ].join(' '))
    .join(' ');
}

export function evaluateScenario(
  scenarioName: string,
  expectation: ScenarioExpectation,
  findings: Finding[],
): ScenarioEvalResult {
  const checks: EvalDetail[] = [];
  const top = findings[0];

  // 1. Minimum findings count
  checks.push({
    check: 'minFindings',
    pass: findings.length >= expectation.minFindings,
    detail: `Expected >= ${expectation.minFindings}, got ${findings.length}`,
  });

  // 2. Top finding title matches
  const topTitleMatch =
    top !== undefined &&
    expectation.topFindingMustMatch.some((re) => re.test(top.title));
  checks.push({
    check: 'topFindingTitle',
    pass: topTitleMatch,
    detail: top
      ? `Top finding: "${top.title}"`
      : 'No findings produced',
  });

  // 3. Top finding severity
  const topSeverityMatch =
    top !== undefined &&
    expectation.topFindingSeverity.includes(top.severity);
  checks.push({
    check: 'topFindingSeverity',
    pass: topSeverityMatch,
    detail: top
      ? `Got "${top.severity}", expected one of [${expectation.topFindingSeverity.join(', ')}]`
      : 'No findings',
  });

  // 4. Top finding confidence
  const topConfMatch =
    top !== undefined &&
    top.confidence >= expectation.topFindingMinConfidence;
  checks.push({
    check: 'topFindingConfidence',
    pass: topConfMatch,
    detail: top
      ? `Got ${(top.confidence * 100).toFixed(0)}%, min ${(expectation.topFindingMinConfidence * 100).toFixed(0)}%`
      : 'No findings',
  });

  // 5. Evidence citation coverage
  const allPaths = findings.flatMap((f) => f.evidence.map((e) => e.path));
  for (const pattern of expectation.mustCiteEvidence) {
    const cited = allPaths.some((p) => pattern.test(p));
    checks.push({
      check: `mustCiteEvidence: ${pattern.source}`,
      pass: cited,
      detail: cited ? 'Found matching evidence path' : `No evidence path matches /${pattern.source}/`,
    });
  }

  // 6. No hallucinations
  const fullText = allFindingsText(findings);
  for (const pattern of expectation.mustNotHallucinate) {
    const found = pattern.test(fullText);
    checks.push({
      check: `mustNotHallucinate: ${pattern.source}`,
      pass: !found,
      detail: found
        ? `HALLUCINATION DETECTED: /${pattern.source}/ found in findings text`
        : 'Clean — pattern not found',
    });
  }

  // 7. Root cause match
  const rootCauseText = top?.reasoningSummary ?? '';
  const rootCauseMatch = expectation.rootCauseMustMatch.some((re) =>
    re.test(rootCauseText),
  );
  checks.push({
    check: 'rootCauseMatch',
    pass: rootCauseMatch,
    detail: rootCauseMatch
      ? 'Root cause reasoning matches expected pattern'
      : `Root cause "${rootCauseText.slice(0, 100)}" did not match any expected pattern`,
  });

  // 8. Required identifiers
  for (const id of expectation.mustMentionIdentifiers) {
    const mentioned = fullText.toLowerCase().includes(id.toLowerCase());
    checks.push({
      check: `mustMention: ${id}`,
      pass: mentioned,
      detail: mentioned ? `Found "${id}"` : `"${id}" not found in any finding`,
    });
  }

  const passCount = checks.filter((c) => c.pass).length;
  const score = checks.length > 0 ? passCount / checks.length : 0;

  return {
    scenario: scenarioName,
    pass: checks.every((c) => c.pass),
    score,
    checks,
  };
}

export function buildEvalReport(
  results: Record<string, ScenarioEvalResult>,
): EvalReport {
  const scenarios = results;
  const allResults = Object.values(scenarios);
  const overallPass = allResults.every((r) => r.pass);
  const overallScore =
    allResults.length > 0
      ? allResults.reduce((sum, r) => sum + r.score, 0) / allResults.length
      : 0;

  return {
    timestamp: new Date().toISOString(),
    scenarios,
    overallPass,
    overallScore,
  };
}

import type { BundleProfile } from '../types/index.js';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface TraceStep {
  name: string;
  startedAt: string;
  completedAt?: string;
  artifactsProcessed: number;
  errors?: string[];
}

export interface InvestigationTrace {
  bundlePath: string;
  startedAt: string;
  completedAt?: string;
  steps: TraceStep[];
  profile?: BundleProfile;
}

// ---------------------------------------------------------------------------
// Factory
// ---------------------------------------------------------------------------

/**
 * Creates a new investigation trace for the given bundle path.
 */
export function createTrace(bundlePath: string): InvestigationTrace {
  return {
    bundlePath,
    startedAt: new Date().toISOString(),
    steps: [],
  };
}

/**
 * Records the start of a new pipeline step and returns its index.
 *
 * The returned index should be passed to {@link completeTraceStep} when the
 * step finishes.
 */
export function startTraceStep(trace: InvestigationTrace, name: string): number {
  const step: TraceStep = {
    name,
    startedAt: new Date().toISOString(),
    artifactsProcessed: 0,
  };
  trace.steps.push(step);
  return trace.steps.length - 1;
}

/**
 * Marks a trace step as completed, recording the finish time, artifact count
 * and any errors encountered.
 */
export function completeTraceStep(
  trace: InvestigationTrace,
  stepIndex: number,
  artifactsProcessed: number,
  errors?: string[],
): void {
  const step = trace.steps[stepIndex];
  if (!step) return;

  step.completedAt = new Date().toISOString();
  step.artifactsProcessed = artifactsProcessed;
  if (errors && errors.length > 0) {
    step.errors = errors;
  }
}

/**
 * Marks the entire trace as completed.
 */
export function completeTrace(
  trace: InvestigationTrace,
  profile?: BundleProfile,
): void {
  trace.completedAt = new Date().toISOString();
  if (profile) {
    trace.profile = profile;
  }
}

import type { ArtifactCategory } from './bundle.js';

export type FindingSeverity = 'critical' | 'high' | 'medium' | 'low' | 'info';

/**
 * Qualitative indicator of how well-supported the confidence score is.
 *
 * - `'strong'`   — ≥3 evidence items from ≥2 distinct source types, 0 missing decisive
 * - `'moderate'` — 2 evidence items OR exactly 1 missing decisive item
 * - `'weak'`     — 1 evidence item OR ≥2 missing decisive items
 *
 * Displayed alongside the numeric percentage so the user knows whether `80%`
 * represents a well-grounded conclusion or a tentative estimate that could
 * shift significantly with additional evidence.
 */
export type ConfidenceQuality = 'strong' | 'moderate' | 'weak';

export interface Evidence {
  path: string;
  note: string;
  artifactType?: ArtifactCategory;
  timestamp?: string;
}

export interface Finding {
  id: string;
  title: string;
  severity: FindingSeverity;
  /** Confidence score in the range [0, 1] */
  confidence: number;
  affectedComponents: string[];
  reasoningSummary: string;
  evidence: Evidence[];
  contradictionsChecked: string[];
  recommendedAction: string;
  missingEvidence: string[];
  /**
   * Qualitative confidence indicator — set by the verifier after all evidence
   * has been collected and contradiction checks run.  `undefined` when the
   * finding has not yet been through the verification pass.
   */
  confidenceQuality?: ConfidenceQuality;
}

