// ---------------------------------------------------------------------------
// LLM Response Recorder / Replay
// ---------------------------------------------------------------------------
//
// Provides record/replay for LLM investigation calls so nightly CI can
// capture real API responses and PR CI can replay them deterministically.
//
// Mode is controlled via `SBI_AI_MODE` environment variable:
//   - `live`   — real API calls, no recording (default)
//   - `record` — real API calls, save cassettes to disk
//   - `replay` — load cassettes, match by seed key, return cached response
//
// Cassettes are keyed by a hash of seed.id + seed.category so that prompt
// refactoring does not invalidate recordings. If a seed has no matching
// cassette during replay, the call returns empty findings (not an error).

import * as fsp from 'fs/promises';
import * as path from 'path';
import * as crypto from 'crypto';
import type { AIFinding } from './schemas.js';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type RecorderMode = 'live' | 'record' | 'replay';

export interface Cassette {
  seedKey: string;
  seedId: string;
  seedCategory: string;
  request: { system: string; user: string };
  response: { findings: AIFinding[]; rawResponse: string };
  model: string;
  timestamp: string;
}

export interface CassetteStore {
  version: string;
  cassettes: Record<string, Cassette>;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Computes a stable cassette key from a seed's identity fields.
 *
 * Uses `seed.id + seed.category` so that prompt text changes don't
 * invalidate recordings — only seed identity matters.
 */
export function cassetteSeedKey(seedId: string, seedCategory: string): string {
  const hash = crypto
    .createHash('sha256')
    .update(`${seedId}::${seedCategory}`)
    .digest('hex')
    .slice(0, 16);
  return `${seedCategory}:${hash}`;
}

/**
 * Reads the `SBI_AI_MODE` environment variable and normalises it to a
 * valid {@link RecorderMode}. Defaults to `'live'`.
 */
export function getRecorderMode(): RecorderMode {
  const raw = (process.env['SBI_AI_MODE'] ?? 'live').trim().toLowerCase();
  if (raw === 'record' || raw === 'replay') return raw;
  return 'live';
}

// ---------------------------------------------------------------------------
// CassetteRecorder
// ---------------------------------------------------------------------------

/**
 * Records and replays LLM investigation call responses.
 *
 * ### Recording flow (nightly CI)
 * ```typescript
 * const recorder = new CassetteRecorder('record', './test/cassettes');
 * // After each real LLM call:
 * recorder.record(seedId, seedCategory, request, response, model);
 * // At the end:
 * await recorder.flush();
 * ```
 *
 * ### Replay flow (PR CI)
 * ```typescript
 * const recorder = new CassetteRecorder('replay', './test/cassettes');
 * await recorder.load();
 * // Instead of calling the LLM:
 * const cached = recorder.replay(seedId, seedCategory);
 * if (cached) { use cached.response } else { skip or warn }
 * ```
 */
export class CassetteRecorder {
  readonly mode: RecorderMode;
  private readonly dir: string;
  private store: CassetteStore;

  constructor(mode: RecorderMode, cassetteDir: string) {
    this.mode = mode;
    this.dir = cassetteDir;
    this.store = { version: '1', cassettes: {} };
  }

  /** Returns the file path for the consolidated cassette store. */
  get storePath(): string {
    return path.join(this.dir, 'cassettes.json');
  }

  /** Number of cassettes currently held in memory. */
  get size(): number {
    return Object.keys(this.store.cassettes).length;
  }

  /**
   * Records a single LLM call.
   *
   * Only takes effect in `record` mode; no-ops in other modes.
   */
  record(
    seedId: string,
    seedCategory: string,
    request: { system: string; user: string },
    response: { findings: AIFinding[]; rawResponse: string },
    model: string,
  ): void {
    if (this.mode !== 'record') return;

    const key = cassetteSeedKey(seedId, seedCategory);
    this.store.cassettes[key] = {
      seedKey: key,
      seedId,
      seedCategory,
      request,
      response,
      model,
      timestamp: new Date().toISOString(),
    };
  }

  /**
   * Retrieves a cached response for the given seed identity.
   *
   * Returns `undefined` when no matching cassette exists.
   */
  replay(
    seedId: string,
    seedCategory: string,
  ): Cassette | undefined {
    const key = cassetteSeedKey(seedId, seedCategory);
    return this.store.cassettes[key];
  }

  /**
   * Loads cassettes from disk into memory.
   *
   * Safe to call in any mode — silently returns if the file doesn't exist.
   */
  async load(): Promise<void> {
    try {
      const raw = await fsp.readFile(this.storePath, 'utf-8');
      const parsed = JSON.parse(raw) as CassetteStore;
      if (parsed.version === '1' && typeof parsed.cassettes === 'object') {
        this.store = parsed;
      }
    } catch {
      // File not found or parse error — start with empty store
      this.store = { version: '1', cassettes: {} };
    }
  }

  /**
   * Writes all recorded cassettes to disk.
   *
   * Only takes effect in `record` mode; no-ops in other modes.
   */
  async flush(): Promise<void> {
    if (this.mode !== 'record') return;

    await fsp.mkdir(this.dir, { recursive: true });
    await fsp.writeFile(
      this.storePath,
      JSON.stringify(this.store, null, 2),
      'utf-8',
    );
  }

  /** Returns all stored cassette keys (for diagnostics). */
  keys(): string[] {
    return Object.keys(this.store.cassettes);
  }

  /** Checks if a cassette exists for the given seed. */
  has(seedId: string, seedCategory: string): boolean {
    return this.replay(seedId, seedCategory) !== undefined;
  }
}

// ---------------------------------------------------------------------------
// LLM Client
// ---------------------------------------------------------------------------
//
// Thin wrapper around the OpenAI chat completions API for structured AI
// investigations.
//
// Design principles:
// - Never throws — all API/network/parse errors are caught, logged with
//   console.warn, and returned as empty findings arrays.
// - Uses JSON mode (response_format: { type: 'json_object' }) to ensure
//   the model returns valid JSON that can be parsed and validated.
// - Validates the parsed response through `validateAIFindings` before
//   returning — invalid findings are dropped, not thrown.

import OpenAI from 'openai';
import type { AIConfig } from './config.js';
import type { AIFinding } from './schemas.js';
import { validateAIFindings } from './schemas.js';
import type { HydeLLMClient } from './hyde.js';

// ---------------------------------------------------------------------------
// AIFindingResponse
// ---------------------------------------------------------------------------

/**
 * The response produced by a single LLM investigation call.
 *
 * On API failure, `findings` is empty and `rawResponse` is absent.
 * On JSON parse failure, `findings` is empty and `rawResponse` holds the
 * unparseable string for debugging.
 */
export interface AIFindingResponse {
  /** Validated, sanitised findings. Empty when the call fails or returns nothing useful. */
  findings: AIFinding[];
  /** Raw JSON string returned by the model (present even on validation failure). */
  rawResponse?: string;
}

// ---------------------------------------------------------------------------
// LLMClient
// ---------------------------------------------------------------------------

/**
 * Wraps the OpenAI chat completions API for structured K8s investigation.
 *
 * Implements {@link HydeLLMClient} so it can be passed directly to
 * `generateHypotheticalDocument` without any adapter.
 *
 * Instantiate with a loaded {@link AIConfig} (must have `enabled: true` and a
 * valid `apiKey`). If the config is disabled, callers should not construct
 * this class — use the `isAIEnabled` guard from `config.ts` first.
 *
 * Supports both cloud (OpenAI) and local (Ollama, llama.cpp, vLLM, LM Studio)
 * backends via the `llmUrl` config field. Local backends use an OpenAI-
 * compatible API, so the same client works for both.
 */
export class LLMClient implements HydeLLMClient {
  private readonly client: OpenAI;
  private readonly model: string;

  constructor(config: AIConfig) {
    this.client = new OpenAI({
      apiKey: config.apiKey,
      baseURL: config.llmUrl,
    });
    this.model = config.model;
  }

  /**
   * Generates free-form text given a system and user prompt.
   *
   * Unlike `investigateSeed`, this method does NOT use JSON mode — the model
   * response is returned as a plain string.
   *
   * **Does not swallow errors** — throws on network/API failure so that
   * callers (e.g. `generateHypotheticalDocument`) can detect failure and apply
   * their own fallback logic.
   *
   * @param systemPrompt - System-level context for the generation task.
   * @param userPrompt   - User-facing prompt.
   * @returns Generated text string.  Empty string if the model returns no content.
   */
  async generateText(systemPrompt: string, userPrompt: string): Promise<string> {
    const response = await this.client.chat.completions.create({
      model: this.model,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
    });

    return response.choices[0]?.message?.content ?? '';
  }

  /**
   * Calls the LLM with a system + user prompt pair and returns structured
   * findings.
   *
   * Uses `response_format: { type: 'json_object' }` so the model always
   * returns a JSON object. The response is parsed and validated through
   * {@link validateAIFindings} before being returned.
   *
   * **Graceful degradation**: any error (network, API, JSON parse, validation)
   * is caught and logged via `console.warn`. The method always resolves, never
   * rejects.
   *
   * @param systemPrompt - System prompt with grounding rules and playbook.
   * @param userPrompt   - User prompt with hypothesis, chunks, and schema.
   * @returns AIFindingResponse — validated findings + optional raw response.
   */
  async investigateSeed(
    systemPrompt: string,
    userPrompt: string,
  ): Promise<AIFindingResponse> {
    let rawResponse: string | undefined;

    try {
      const response = await this.client.chat.completions.create({
        model: this.model,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
      });

      rawResponse = response.choices[0]?.message?.content ?? '{}';

      let parsed: unknown;
      try {
        parsed = JSON.parse(rawResponse);
      } catch (parseError) {
        console.warn(
          `[LLMClient] Failed to parse JSON response: ${parseError instanceof Error ? parseError.message : String(parseError)}`,
        );
        return { findings: [], rawResponse };
      }

      // Extract the `findings` array from the parsed JSON object
      const rawFindings =
        parsed !== null &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed) &&
        'findings' in parsed
          ? (parsed as Record<string, unknown>)['findings']
          : [];

      const findings = validateAIFindings(rawFindings);

      return { findings, rawResponse };
    } catch (error) {
      console.warn(
        `[LLMClient] API call failed: ${error instanceof Error ? error.message : String(error)}`,
      );
      return { findings: [] };
    }
  }
}

