  /**
   * High-level narrative written for a human reader — typically 2–4 sentences
   * summarising the most critical finding, the overall confidence, and the
   * recommended immediate action.
   */
  executiveSummary: string;

  /**
   * Verified, deduplicated findings sorted by severity then confidence
   * (highest first).  This is the primary payload for report consumers.
   */
  findings: Finding[];

  /**
   * The single most likely root cause for the observed symptoms.  Derived
   * from the highest-ranked finding; may be `null` when no findings exist.
   */
  rootCause: string | null;

  /**
   * Flat list of all evidence references cited across every finding, with
   * duplicates removed.  Useful for report sections that list all touched
   * files in one place.
   */
  evidenceReferences: Array<{ path: string; note: string }>;

  /**
   * Union of `contradictionsChecked` strings across all findings, with
   * duplicates removed.  Surfaces the "what we checked and ruled out"
   * narrative for the reader.
   */
  contradictions: string[];

  /**
   * Consolidated recommended next steps drawn from `recommendedAction` on
   * every finding (highest-severity first).  Duplicates are removed.
   */
  nextSteps: string[];

  /**
   * Union of `missingEvidence` strings across all findings, with duplicates
   * removed.  Tells the reader what additional data would improve confidence.
   */
  missingEvidence: string[];

  /**
   * Suggestions for improving the support bundle spec — collectors, analyzers,
   * or redaction rules that should be added to prevent evidence gaps in future
   * bundles.  Empty when the investigation found sufficient coverage.
   */
  specRecommendations: SpecRecommendation[];
}

import * as fsp from 'fs/promises';
import * as path from 'path';
import type { InvestigationReport } from './types.js';
import { cleanEvidencePath, humanizeTitle } from './display-helpers.js';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Identifies the schema version of the JSON output.  Increment on breaking changes. */
const REPORT_SCHEMA_VERSION = '1.0.0';

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Serializes an {@link InvestigationReport} to a well-structured JSON string.
 *
 * The output includes:
 * - Report metadata: `schemaVersion` and `generatedAt` (ISO-8601 timestamp).
 * - All top-level report fields: `executiveSummary`, `rootCause`,
 *   `evidenceReferences`, `contradictions`, `nextSteps`, `missingEvidence`,
 *   and `specRecommendations`.
 * - A `findings` array where every finding is serialized with its full set of
 *   fields: `id`, `title`, `severity`, `confidence`, `affectedComponents`,
 *   `reasoningSummary`, `evidence`, `contradictionsChecked`,
 *   `recommendedAction`, and `missingEvidence`.
 *
 * The JSON is formatted with 2-space indentation for human readability.  The
 * output is safe for `JSON.parse` round-tripping — no circular references, no
 * class instances, no functions.
 *
 * @param report - The investigation report to serialize.
 * @returns A JSON string representing the full investigation report.
 */
export function generateJsonReport(report: InvestigationReport): string {
  const output = {
    schemaVersion: REPORT_SCHEMA_VERSION,
    generatedAt: new Date().toISOString(),
    executiveSummary: report.executiveSummary,
    rootCause: report.rootCause,
    findings: report.findings.map((finding) => {
      const base = {
        id: finding.id,
        title: humanizeTitle(finding.title),
        severity: finding.severity,
        confidence: finding.confidence,
        affectedComponents: finding.affectedComponents.map(cleanEvidencePath),
        reasoningSummary: finding.reasoningSummary,
        evidence: finding.evidence.map((ev) => {
          const evOut: Record<string, unknown> = {
            path: cleanEvidencePath(ev.path),
            note: ev.note,
          };
          if (ev.artifactType !== undefined) {
            evOut['artifactType'] = ev.artifactType;
          }
          if (ev.timestamp !== undefined) {
            evOut['timestamp'] = ev.timestamp;
          }
          return evOut;
        }),
        contradictionsChecked: finding.contradictionsChecked,
        recommendedAction: finding.recommendedAction,
        missingEvidence: finding.missingEvidence,
        ...(finding.confidenceQuality !== undefined
          ? { confidenceQuality: finding.confidenceQuality }
          : {}),
      };
      return base;
    }),
    evidenceReferences: report.evidenceReferences.map((ev) => ({
      path: cleanEvidencePath(ev.path),
      note: ev.note,
    })),
    contradictions: report.contradictions,
    nextSteps: report.nextSteps,
    missingEvidence: report.missingEvidence,
    specRecommendations: report.specRecommendations,
  };

  return JSON.stringify(output, null, 2);
}

/**
 * Writes an {@link InvestigationReport} as a JSON file to disk.
 *
 * The report is written to `findings.json` inside `outputDir`.  The directory
 * is created recursively if it does not already exist.
 *
 * @param report    - The investigation report to write.
 * @param outputDir - Directory where `findings.json` will be created.
 * @returns The absolute path of the written file.
 */
export async function writeJsonReport(
  report: InvestigationReport,
  outputDir: string,
): Promise<string> {
  const resolvedOutputDir = path.resolve(outputDir);
  await fsp.mkdir(resolvedOutputDir, { recursive: true });
  const outFile = path.join(resolvedOutputDir, 'findings.json');
  await fsp.writeFile(outFile, generateJsonReport(report), 'utf-8');
  return outFile;
}

import * as fsp from 'fs/promises';
import * as path from 'path';
import type { Finding, FindingSeverity } from '../types/index.js';
import type { InvestigationReport, SpecRecommendation } from './types.js';
import { isAIFinding } from './report-builder.js';
import {
  cleanEvidencePath,
  humanizeTitle,
  humanizeReasoning,
  collapseEvidence,
  formatSummaryCard,
} from './display-helpers.js';

// ---------------------------------------------------------------------------
// Severity helpers
// ---------------------------------------------------------------------------

/**
 * Maps a {@link FindingSeverity} to a Markdown-renderable badge string.
 * Uses text-only markers (no emoji) for maximum terminal compatibility.
 */
function severityBadge(severity: FindingSeverity): string {
  const labels: Record<FindingSeverity, string> = {
    critical: '[!!] CRITICAL',
    high: '[!] HIGH',
    medium: '[~] MEDIUM',
    low: '[-] LOW',
    info: '[i] INFO',
  };
  return `**${labels[severity]}**`;
}

/**
 * Returns a confidence percentage string with an optional quality indicator.
 * e.g. `0.87` with quality `'strong'` → `"87% (strong)"`.
 * Clamps the value to [0, 1] before formatting.
 */
function formatConfidence(confidence: number, quality?: Finding['confidenceQuality']): string {
  const clamped = Math.min(1, Math.max(0, confidence));
  const pct = `${Math.round(clamped * 100)}%`;
  if (quality === undefined) return pct;
  return `${pct} (${quality})`;
}

// ---------------------------------------------------------------------------
// Section renderers
// ---------------------------------------------------------------------------

/**
 * Renders the top-level H1 title and executive summary.
 */
function renderExecutiveSummary(report: InvestigationReport): string {
  const lines: string[] = [];
  lines.push('# Investigation Report');
  lines.push('');

  // "Start here" card for the top finding
  if (report.findings.length > 0) {
    lines.push(formatSummaryCard(report.findings[0]!, report.findings.length));
    lines.push('');
  }

  lines.push('## Executive Summary');
  lines.push('');
  lines.push(report.executiveSummary);
  lines.push('');

  if (report.rootCause !== null) {
    lines.push(`**Root Cause:** ${humanizeReasoning(report.rootCause)}`);
    lines.push('');
  }

  return lines.join('\n');
}

/**
 * Renders the evidence table for a single finding.
 *
 * | Path | Note |
 * |------|------|
 * | …   | …   |
 */
function renderEvidenceTable(finding: Finding): string {
  if (finding.evidence.length === 0) {
    return '_No evidence recorded._\n';
  }

  const collapsed = collapseEvidence(finding.evidence);
  const rows = collapsed.map((ev) => {
    const cleanedPath = cleanEvidencePath(ev.path);
    const escapedPath = cleanedPath.replace(/\|/g, '\\|');
    const escapedNote = ev.note.replace(/\|/g, '\\|');
    return `| \`${escapedPath}\` | ${escapedNote} |`;
  });

  return ['| Path | Note |', '|------|------|', ...rows].join('\n') + '\n';
}

/**
 * Renders all findings as numbered H3 subsections, sorted by their position
 * in the supplied `findings` array (callers are responsible for ordering).
 */
function renderFindings(findings: Finding[]): string {
  if (findings.length === 0) {
    return '## Findings\n\n_No findings recorded._\n';
  }

  const lines: string[] = [];
  lines.push('## Findings');
  lines.push('');

  findings.forEach((finding, idx) => {
    const aiTag = isAIFinding(finding) ? ' [AI-assisted]' : '';
    const displayTitle = humanizeTitle(finding.title);
    lines.push(`### ${idx + 1}. ${displayTitle}${aiTag}`);
    lines.push('');

    // Severity badge + confidence on the same line for scannability
    lines.push(
      `${severityBadge(finding.severity)} · Confidence: **${formatConfidence(finding.confidence, finding.confidenceQuality)}**`,
    );
    lines.push('');

    // Affected components (clean temp paths)
    if (finding.affectedComponents.length > 0) {
      lines.push(
        `**Affected Components:** ${finding.affectedComponents.map((c) => `\`${cleanEvidencePath(c)}\``).join(', ')}`,
      );
      lines.push('');
    }

    // Reasoning
    lines.push('**Reasoning**');
    lines.push('');
    lines.push(humanizeReasoning(finding.reasoningSummary));
    lines.push('');

    // Evidence table
    lines.push('**Evidence**');
    lines.push('');
    lines.push(renderEvidenceTable(finding));

    // Contradictions checked
    if (finding.contradictionsChecked.length > 0) {
      lines.push('**Contradictions Checked**');
      lines.push('');
      for (const contradiction of finding.contradictionsChecked) {
        lines.push(`- ${contradiction}`);
      }
      lines.push('');
    }

    // Recommended action
    lines.push('**Recommended Action**');
    lines.push('');
    lines.push(finding.recommendedAction);
    lines.push('');
  });

  return lines.join('\n');
}

/**
 * Renders the missing evidence section listing all gaps consolidated across
 * all findings.
 */
function renderMissingEvidence(missingEvidence: string[]): string {
  const lines: string[] = [];
  lines.push('## Missing Evidence');
  lines.push('');

  if (missingEvidence.length === 0) {
    lines.push('_No missing evidence identified._');
    lines.push('');
  } else {
    for (const item of missingEvidence) {
      lines.push(`- ${item}`);
    }
    lines.push('');
  }

  return lines.join('\n');
}

/**
 * Renders the spec improvement recommendations section.
 */
function renderSpecRecommendations(recommendations: SpecRecommendation[]): string {
  const lines: string[] = [];
  lines.push('## Spec Improvement Recommendations');
  lines.push('');

  if (recommendations.length === 0) {
    lines.push('_No spec improvements recommended._');
    lines.push('');
    return lines.join('\n');
  }

  recommendations.forEach((rec, idx) => {
    const typeLabel =
      rec.type === 'collector'
        ? '[+] Collector'
        : rec.type === 'analyzer'
          ? '[?] Analyzer'
          : '[x] Redaction';

    lines.push(`### ${idx + 1}. ${typeLabel}`);
    lines.push('');
    lines.push(rec.description);
    lines.push('');
    lines.push(`_Rationale: ${rec.rationale}_`);
    lines.push('');
  });

  return lines.join('\n');
}

/**
 * Renders the investigation metadata footer.
 */
function renderMetadataFooter(report: InvestigationReport, generatedAt: string): string {
  const lines: string[] = [];
  lines.push('---');
  lines.push('');
  lines.push('## Investigation Metadata');
  lines.push('');
  lines.push(`| Field | Value |`);
  lines.push(`|-------|-------|`);
  lines.push(`| Generated At | ${generatedAt} |`);
  lines.push(`| Total Findings | ${report.findings.length} |`);
  lines.push(`| Evidence References | ${report.evidenceReferences.length} |`);
  lines.push(`| Contradictions Checked | ${report.contradictions.length} |`);
  lines.push(`| Spec Recommendations | ${report.specRecommendations.length} |`);
  lines.push('');

  return lines.join('\n');
}

