  return [
    `### Chunk ${index + 1}`,
    `Source: ${chunk.artifactId} (${category}, ${lineRange})`,
    `Chunk ID: ${chunk.id}`,
    `Summary: ${chunk.summary}`,
    '',
    '```',
    chunk.content,
    '```',
  ].join('\n');
}

