      outputDir: '/tmp/out',
      verbose: false,
      trace: false,
      noAi: false,
      tui: true,
    });

    await expect(runCli(['node', 'sbi', 'analyze', '/tmp/bundle.tar.gz', '--tui'], options)).resolves.toBe(0);

    expect(loadTUIMock).toHaveBeenCalledOnce();
    expect(renderTUIMock).toHaveBeenCalledWith('/tmp/bundle.tar.gz', {
      outputDir: '/tmp/out',
      verbose: false,
